    public static int blinn_phong_attr_slot(string attr_name) {
        if (attr_name == "in_pos") {
            return 0;
        }
        if (attr_name == "in_normal") {
            return 1;
        }
        if (attr_name == "in_uv") {
            return 2;
        }
        if (attr_name == "in_tangent") {
            return 3;
        }
        if (attr_name == "in_model_0") {
            return 4;
        }
        if (attr_name == "in_model_1") {
            return 5;
        }
        if (attr_name == "in_model_2") {
            return 6;
        }
        if (attr_name == "in_model_3") {
            return 7;
        }
        if (attr_name == "in_custom") {
            return 8;
        }
        return -1;
    }
    public static int blinn_phong_texture_slot(string tex_name) {
        if (tex_name == "normal_map") {
