    public static int blinn_phong_uniform_offset(string ub_name, string u_name) {
        if (ub_name == "blinn_phong_vs_params") {
            if (u_name == "view_proj") {
                return 0;
            }
            if (u_name == "camera_pos") {
                return 64;
            }
            if (u_name == "dir_shadow_vp") {
                return 80;
            }
        }
        if (ub_name == "blinn_phong_fs_params") {
            if (u_name == "material_kd_alpha") {
                return 0;
            }
            if (u_name == "material_ks_shin") {
                return 16;
            }
            if (u_name == "ambient_num") {
                return 32;
            }
            if (u_name == "cam_pos_pad") {
                return 48;
            }
            if (u_name == "lights_data") {
                return 64;
            }
            if (u_name == "spot_shadow_vp") {
                return 2112;
            }
            if (u_name == "point_shadow_vp") {
                return 2624;
            }
        }
        return -1;
    }
